// Pemetaan tanda tangan Reviewer (REVIEWED BY)
export const REVIEWED_BY_SIGNATURES: Record<string, string> = {
  'Arif Budiman': ARIF_BUDIMAN_SIGNATURE_BASE64,
  'arif@utt.com': ARIF_BUDIMAN_SIGNATURE_BASE64,
  'arif.budiman@utt.com': ARIF_BUDIMAN_SIGNATURE_BASE64,
  'Arif': ARIF_BUDIMAN_SIGNATURE_BASE64,
};

/**
 * Helper: Ambil tanda tangan base64 berdasarkan email atau nama insinyur
 * @param identifier Email atau nama insinyur
 * @returns Tanda tangan base64 PNG atau fallback null
 */
export function getEngineerSignature(identifier?: string | null): string | null {
  if (!identifier) return null;
  const trimmed = identifier.trim();
  if (PREPARED_BY_SIGNATURES[trimmed]) {
    return cleanSignature(PREPARED_BY_SIGNATURES[trimmed]) || null;
  }
  const lower = trimmed.toLowerCase();
  for (const [key, val] of Object.entries(PREPARED_BY_SIGNATURES)) {
    if (key.toLowerCase() === lower) {
      return cleanSignature(val) || null;
    }
  }
  return null;
}

/**
 * Helper: Normalisasi nama insinyur ke nama lengkap resmi (Agil Zakia Rahman, Muhammad Salman Abdurohman, Asep Mohammad Fauzi)
 */
export function normalizeEngineerName(identifier?: string | null): string {
  if (!identifier) return 'Muhammad Salman Abdurohman';
  const trimmed = identifier.trim();
  const lower = trimmed.toLowerCase();
  if (lower === 'agil' || lower.includes('agil')) return 'Agil Zakia Rahman';
  if (lower === 'salman' || lower.includes('salman')) return 'Muhammad Salman Abdurohman';
  if (lower === 'asep' || lower.includes('asep')) return 'Asep Mohammad Fauzi';
  if (lower === 'gilang' || lower.includes('gilang') || lower.includes('nugroho')) return 'Nugroho Gilang Ramadhan';
  return trimmed;
}

/**
 * Helper: Validasi string Base64 tanda tangan (bukan kosong, bukan dummy black box)
 */
export function isValidSignature(sign?: string | null): boolean {
  if (!sign || typeof sign !== 'string') return false;
  const trimmed = sign.trim();
  if (!trimmed || trimmed === '' || trimmed === 'null' || trimmed === 'undefined') return false;
  // Filter out corrupted dummy black box placeholder
  if (trimmed.includes('iVBORw0KGgoAAAANSUhEUgAAAZAAAAEYCAIAAAD9Pjcu')) return false;
  return trimmed.startsWith('data:image/');
}

/**
 * Helper: Bersihkan tanda tangan (kembalikan string valid atau kosong)
 */
export function cleanSignature(sign?: string | null): string {
  if (!sign || !isValidSignature(sign)) return '';
  return sign.trim();
}

/**
 * Helper: Ambil tanda tangan base64 Reviewer (Arif Budiman)
 */
export function getReviewerSignature(identifier?: string | null): string | null {
  if (!identifier) return ARIF_BUDIMAN_SIGNATURE_BASE64;
  const trimmed = identifier.trim();
  if (REVIEWED_BY_SIGNATURES[trimmed]) {
    return cleanSignature(REVIEWED_BY_SIGNATURES[trimmed]) || null;
  }
  const lower = trimmed.toLowerCase();
  if (lower.includes('arif') || lower.includes('budiman')) {
    return ARIF_BUDIMAN_SIGNATURE_BASE64;
  }
  return null;
}

